import sys


def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    a = sorted(map(int, data[1:1 + n]))
    d = min(a[k + 1] - a[k] for k in range(n - 1))
    cnt = 0
    if d == 0:
        run = 1
        for k in range(1, n):
            if a[k] == a[k - 1]:
                run += 1
            else:
                cnt += run * (run - 1) // 2
                run = 1
        cnt += run * (run - 1) // 2
    else:
        for k in range(n - 1):
            if a[k + 1] - a[k] == d:
                cnt += 1
    print(d, cnt)


main()
